SELECT
count(*)
FROM
b_marketing_task
WHERE
`status`=1

	AND api_code = #{apiCode}


	AND create_time >= #{queryBeginDate}


	AND create_time <= #{queryEndDate}


	AND
	monitor_status=#{monitorStatus}


	AND
	strategy_id=#{strategyId}


	AND
	frequency=#{frequency}

SELECT
*
FROM
b_marketing_task
WHERE
`status`=1

	AND api_code = #{apiCode}


	AND create_time >= #{queryBeginDate}


	AND create_time <= #{queryEndDate}


	AND
	monitor_status=#{monitorStatus}


	AND
	strategy_id=#{strategyId}


	AND
	frequency=#{frequency}


	AND
	cus_batch=#{cusBatch}

order by create_time desc
LIMIT #{start},#{limit}

